(async()=>{const out={},set=document.fonts;for(const mode of ['normal','delete','late-add']){document.title=mode;const face=new FontFace('EventProbe','url(data:font/woff2;base64,'+btoa(mode)+')'),events=[];const handler=e=>events.push([e.type,Object.prototype.toString.call(e),e.fontfaces?.length??null]);for(const name of ['loading','loadingdone','loadingerror'])set.addEventListener(name,handler);if(mode!=='late-add')set.add(face);const p=face.load().catch(e=>e.name);if(mode==='delete')set.delete(face);if(mode==='clear')set.clear();if(mode==='late-add')set.add(face);out[mode+'-immediate']=[set.status,face.status];await p;await new Promise(r=>setTimeout(r,20));out[mode]=[set.status,events];for(const name of ['loading','loadingdone','loadingerror'])set.removeEventListener(name,handler);set.delete(face)}document.title='done';return out})()
